    43→/// Maximum number of automatic token refresh attempts per API call
    44→const MAX_AUTO_REFRESH_ATTEMPTS: u32 = 1;
    45→
    46→/// Result type for token refresh operations
    47→pub type TokenRefreshResult = Pin<Box<dyn Future<Output = Result<String, SyncError>> + Send>>;
    48→
    49→/// Trait for providing token refresh functionality to GarminClient.
    50→///
    51→/// Implement this trait to enable automatic token refresh when the access token
    52→/// expires during API calls. When a `TokenExpired` error is encountered, the
    53→/// client will call `refresh_token()` to get a new access token and retry the
    54→/// request.
    55→///
    56→/// # Example
    57→///
    58→/// ```ignore
    59→/// use std::sync::Arc;
    60→/// use tokio::sync::RwLock;
    61→///
    62→/// struct MyTokenRefresher {
    63→///     oauth_handler: Arc<OAuthHandler>,
    64→/// }
    65→///
    66→/// impl TokenRefresher for MyTokenRefresher {
    67→///     fn refresh_token(&self) -> TokenRefreshResult {
    68→///         let handler = self.oauth_handler.clone();
    69→///         Box::pin(async move {
    70→///             let tokens = handler.refresh_token(SyncPlatform::GarminConnect).await?;
    71→///             Ok(tokens.access_token)
    72→///         })
    73→///     }
    74→/// }
    75→/// ```
    76→pub trait TokenRefresher: Send + Sync {
    77→    /// Refresh the access token and return the new token.
    78→    ///
    79→    /// This method is called when the client encounters a `TokenExpired` error.
    80→    /// It should:
    81→    /// 1. Use the stored refresh token to get new access/refresh tokens
    82→    /// 2. Store the new tokens appropriately
    83→    /// 3. Return the new access token
    84→    ///
    85→    /// # Returns
    86→    /// A future that resolves to the new access token or an error.
    87→    ///
    88→    /// # Errors
    89→    /// - `AuthorizationRequired` - If the refresh token is also expired
    90→    /// - `RefreshFailed` - If the refresh request fails for other reasons
    91→    /// - `NetworkError` - If the refresh request fails due to network issues
    92→    fn refresh_token(&self) -> TokenRefreshResult;
    93→}
