   167→/// Rate limit information extracted from API response
   168→#[derive(Debug, Clone)]
   169→pub struct RateLimitInfo {
   170→    /// Seconds to wait before retrying (from Retry-After header or default)
   171→    pub retry_after_secs: u64,
   172→    /// Whether this is a hard limit (daily) vs soft limit (per-minute)
   173→    pub is_hard_limit: bool,
   174→}
   175→
   176→impl Default for RateLimitInfo {
   177→    fn default() -> Self {
   178→        Self {
   179→            retry_after_secs: DEFAULT_RATE_LIMIT_RETRY_SECS,
   180→            is_hard_limit: false,
   181→        }
   182→    }
   183→}
   184→
   185→impl RateLimitInfo {
   186→    /// Create rate limit info from HTTP response headers
   187→    pub fn from_headers(headers: &reqwest::header::HeaderMap) -> Self {
   188→        // Try to parse Retry-After header
   189→        let retry_after_secs = headers
   190→            .get("retry-after")
   191→            .and_then(|v| v.to_str().ok())
   192→            .and_then(|v| v.parse::<u64>().ok())
   193→            .unwrap_or(DEFAULT_RATE_LIMIT_RETRY_SECS);
   194→
   195→        // Check for daily limit indicator (varies by API)
   196→        let is_hard_limit = headers
   197→            .get("x-ratelimit-remaining")
   198→            .and_then(|v| v.to_str().ok())
   199→            .and_then(|v| v.parse::<u64>().ok())
   200→            .map(|remaining| remaining == 0)
   201→            .unwrap_or(false);
   202→
   203→        Self {
   204→            retry_after_secs,
   205→            is_hard_limit,
   206→        }
   207→    }
   208→
   209→    /// Get the retry delay as a Duration
   210→    pub fn retry_delay(&self) -> Duration {
   211→        Duration::from_secs(self.retry_after_secs)
   212→    }
   213→}
