   215→/// Extension trait for SyncError to support error categorization and retry logic
   216→pub trait SyncErrorExt {
   217→    /// Get the error category for retry/recovery logic
   218→    fn category(&self) -> ErrorCategory;
   219→
   220→    /// Check if this error should be retried
   221→    fn is_retryable(&self) -> bool;
   222→
   223→    /// Check if this error requires authentication refresh
   224→    fn requires_auth_refresh(&self) -> bool;
   225→
