   551→    /// # Returns
   552→    /// - `Ok(())` if the token was refreshed successfully
   553→    /// - `Err(SyncError)` if no refresher is configured or refresh failed
   554→    async fn attempt_token_refresh(&self) -> Result<(), SyncError> {
   555→        let refresher = {
   556→            let guard = self.token_refresher.read().await;
   557→            guard.clone()
   558→        };
