   583→    /// Execute an async operation with automatic token refresh on expiry.
   584→    ///
   585→    /// This helper method wraps an API call and automatically handles token
   586→    /// refresh when the operation fails with `TokenExpired`. If a token refresher
   587→    /// is configured and the refresh succeeds, the operation is retried once.
   588→    ///
   589→    /// # Type Parameters
   590→    /// * `F` - The async factory function that creates the operation
   591→    /// * `T` - The return type of the operation
   592→    ///
   593→    /// # Arguments
   594→    /// * `operation_name` - Name of the operation for logging
   595→    /// * `operation_factory` - Factory function that creates the async operation
   596→    ///
   597→    /// # Returns
   598→    /// The result of the operation, or an error if the operation and refresh both fail
   599→    async fn with_auto_refresh<F, Fut, T>(
   600→        &self,
   601→        operation_name: &str,
   602→        operation_factory: F,
   603→    ) -> Result<T, SyncError>
   604→    where
   605→        F: Fn() -> Fut,
   606→        Fut: Future<Output = Result<T, SyncError>>,
   607→    {
   608→        let mut attempts = 0;
   609→
   610→        loop {
   611→            match operation_factory().await {
   612→                Ok(result) => return Ok(result),
   613→                Err(SyncError::TokenExpired) if attempts < MAX_AUTO_REFRESH_ATTEMPTS => {
   614→                    attempts += 1;
   615→                    tracing::info!(
   616→                        "Token expired during {}, attempting refresh (attempt {}/{})",
   617→                        operation_name,
   618→                        attempts,
   619→                        MAX_AUTO_REFRESH_ATTEMPTS
   620→                    );
   621→
   622→                    // Try to refresh the token
   623→                    match self.attempt_token_refresh().await {
   624→                        Ok(()) => {
   625→                            tracing::info!("Token refreshed, retrying {}", operation_name);
   626→                            // Continue loop to retry the operation
   627→                        }
   628→                        Err(refresh_error) => {
   629→                            tracing::warn!(
   630→                                "Token refresh failed during {}: {}",
   631→                                operation_name,
   632→                                refresh_error
   633→                            );
   634→                            // If refresh fails with AuthorizationRequired, propagate that
   635→                            // Otherwise, return the original TokenExpired error
   636→                            return Err(match refresh_error {
   637→                                SyncError::AuthorizationRequired => SyncError::AuthorizationRequired,
   638→                                _ => SyncError::TokenExpired,
   639→                            });
   640→                        }
   641→                    }
   642→                }
   643→                Err(e) => return Err(e),
   644→            }
   645→        }
   646→    }
