  2050→    /// Create a valid FIT file header for testing
  2051→    fn create_valid_fit_header() -> Vec<u8> {
  2052→        let mut data = vec![0u8; 16];
  2053→        data[0] = 14; // Header size (14 bytes)
  2054→        data[1] = 0x10; // Protocol version
  2055→        data[2] = 0x00; // Profile version LSB
  2056→        data[3] = 0x00; // Profile version MSB
  2057→        data[4] = 0x00; // Data size LSB
  2058→        data[5] = 0x00;
  2059→        data[6] = 0x00;
  2060→        data[7] = 0x00; // Data size MSB
  2061→        // ".FIT" signature at bytes 8-11
  2062→        data[8] = b'.';
  2063→        data[9] = b'F';
  2064→        data[10] = b'I';
  2065→        data[11] = b'T';
  2066→        data[12] = 0x00; // CRC LSB
  2067→        data[13] = 0x00; // CRC MSB
  2068→        data
  2069→    }
