    20→// ============================================================================
    21→// Mock OAuth Handler
    22→// ============================================================================
    23→
    24→/// Mock OAuth handler for testing that simulates successful authentication
    25→struct MockOAuthHandler {
    26→    /// Simulated tokens per platform
    27→    tokens: Arc<RwLock<HashMap<SyncPlatform, TokenResponse>>>,
    28→    /// Whether to simulate refresh failure
    29→    simulate_refresh_failure: AtomicBool,
    30→    /// Whether to require re-authorization
    31→    simulate_reauth_required: AtomicBool,
    32→    /// Count of refresh attempts
    33→    refresh_count: AtomicU32,
    34→}
    35→
    36→impl MockOAuthHandler {
    37→    fn new() -> Self {
    38→        Self {
    39→            tokens: Arc::new(RwLock::new(HashMap::new())),
    40→            simulate_refresh_failure: AtomicBool::new(false),
    41→            simulate_reauth_required: AtomicBool::new(false),
    42→            refresh_count: AtomicU32::new(0),
    43→        }
    44→    }
    45→
    46→    /// Pre-configure with valid tokens for a platform
    47→    async fn set_tokens(&self, platform: SyncPlatform, tokens: TokenResponse) {
    48→        self.tokens.write().await.insert(platform, tokens);
    49→    }
    50→
    51→    fn set_refresh_failure(&self, should_fail: bool) {
    52→        self.simulate_refresh_failure.store(should_fail, Ordering::SeqCst);
    53→    }
    54→
    55→    fn set_reauth_required(&self, required: bool) {
    56→        self.simulate_reauth_required.store(required, Ordering::SeqCst);
    57→    }
    58→
    59→    fn get_refresh_count(&self) -> u32 {
    60→        self.refresh_count.load(Ordering::SeqCst)
    61→    }
    62→}
    63→
    64→impl OAuthHandler for MockOAuthHandler {
    65→    async fn start_authorization(
    66→        &self,
    67→        platform: SyncPlatform,
    68→    ) -> Result<AuthorizationUrl, SyncError> {
    69→        Ok(AuthorizationUrl {
    70→            url: format!("https://mock.auth/{:?}", platform),
    71→            state: "mock_state".to_string(),
    72→        })
    73→    }
    74→
    75→    async fn handle_callback(
    76→        &self,
    77→        _code: &str,
    78→        _state: &str,
    79→    ) -> Result<TokenResponse, SyncError> {
    80→        Ok(TokenResponse {
    81→            access_token: "mock_access_token".to_string(),
    82→            refresh_token: Some("mock_refresh_token".to_string()),
    83→            expires_at: Utc::now() + Duration::hours(1),
    84→        })
    85→    }
    86→
    87→    async fn refresh_token(&self, platform: SyncPlatform) -> Result<TokenResponse, SyncError> {
    88→        self.refresh_count.fetch_add(1, Ordering::SeqCst);
    89→
    90→        if self.simulate_reauth_required.load(Ordering::SeqCst) {
    91→            return Err(SyncError::AuthorizationRequired);
    92→        }
    93→
    94→        if self.simulate_refresh_failure.load(Ordering::SeqCst) {
    95→            return Err(SyncError::RefreshFailed("Simulated refresh failure".to_string()));
    96→        }
    97→
    98→        let new_tokens = TokenResponse {
    99→            access_token: format!("refreshed_token_{}", self.get_refresh_count()),
   100→            refresh_token: Some("mock_refresh_token".to_string()),
   101→            expires_at: Utc::now() + Duration::hours(1),
   102→        };
   103→
   104→        self.tokens.write().await.insert(platform, new_tokens.clone());
   105→        Ok(new_tokens)
   106→    }
   107→
   108→    fn is_authorized(&self, platform: SyncPlatform) -> bool {
   109→        // Use try_read to avoid blocking
   110→        self.tokens
   111→            .try_read()
   112→            .map(|t| t.contains_key(&platform))
   113→            .unwrap_or(false)
   114→    }
   115→
   116→    fn get_token_status(&self, platform: SyncPlatform) -> TokenStatus {
   117→        if let Ok(tokens) = self.tokens.try_read() {
   118→            if let Some(token) = tokens.get(&platform) {
   119→                let now = Utc::now();
   120→                if token.expires_at <= now {
   121→                    TokenStatus::Expired
   122→                } else if token.expires_at <= now + Duration::minutes(5) {
   123→                    TokenStatus::NeedsRefresh
   124→                } else {
   125→                    let expires_in = (token.expires_at - now).to_std().unwrap_or_default();
   126→                    TokenStatus::Valid { expires_in }
   127→                }
   128→            } else {
   129→                TokenStatus::NotConfigured
   130→            }
   131→        } else {
   132→            TokenStatus::NotConfigured
   133→        }
   134→    }
