     1→//! Garmin Connect API Integration
     2→//!
     3→//! T105: Implement Garmin Connect API upload.
     4→//!
     5→//! This module provides comprehensive error handling for all Garmin Connect API
     6→//! interactions, including:
     7→//! - Rate limiting with retry-after support
     8→//! - Token expiry and refresh handling
     9→//! - Automatic token refresh on expiry
    10→//! - Duplicate activity detection
    11→//! - Network error recovery
    12→//! - FIT file validation
    13→//!
    14→//! ## Upload Processing Model
    15→//!
    16→//! Garmin Connect uses **synchronous** upload processing, unlike Strava which
    17→//! processes uploads asynchronously:
    18→//!
    19→//! - **Garmin Connect**: The upload API immediately returns the activity ID
    20→//!   (or error) in the response. No status polling is required. The upload
    21→//!   completes in a single request/response cycle.
    22→//!
    23→//! - **Strava**: Returns an upload_id immediately, then processes the file
    24→//!   asynchronously. Requires calling `check_upload_status()` to poll for
    25→//!   completion.
    26→//!
    27→//! This means GarminClient does NOT need a `check_upload_status()` method.
    28→//! The `upload_activity()` method returns a `SyncRecord` with `status: Completed`
    29→//! when successful, or an error if the upload fails.
    30→
    31→use super::{SyncError, SyncPlatform, SyncRecord, SyncRecordStatus};
    32→use chrono::Utc;
    33→use reqwest::multipart::{Form, Part};
    34→use reqwest::Client;
    35→use serde::Deserialize;
    36→use std::future::Future;
    37→use std::pin::Pin;
    38→use std::sync::Arc;
    39→use std::time::Duration;
    40→use tokio::sync::RwLock;
    41→use uuid::Uuid;
    42→
    43→/// Maximum number of automatic token refresh attempts per API call
    44→const MAX_AUTO_REFRESH_ATTEMPTS: u32 = 1;
    45→
    46→/// Result type for token refresh operations
    47→pub type TokenRefreshResult = Pin<Box<dyn Future<Output = Result<String, SyncError>> + Send>>;
    48→
    49→/// Trait for providing token refresh functionality to GarminClient.
    50→///
    51→/// Implement this trait to enable automatic token refresh when the access token
    52→/// expires during API calls. When a `TokenExpired` error is encountered, the
    53→/// client will call `refresh_token()` to get a new access token and retry the
    54→/// request.
    55→///
    56→/// # Example
    57→///
    58→/// ```ignore
    59→/// use std::sync::Arc;
    60→/// use tokio::sync::RwLock;
    61→///
    62→/// struct MyTokenRefresher {
    63→///     oauth_handler: Arc<OAuthHandler>,
    64→/// }
    65→///
    66→/// impl TokenRefresher for MyTokenRefresher {
    67→///     fn refresh_token(&self) -> TokenRefreshResult {
    68→///         let handler = self.oauth_handler.clone();
    69→///         Box::pin(async move {
    70→///             let tokens = handler.refresh_token(SyncPlatform::GarminConnect).await?;
    71→///             Ok(tokens.access_token)
    72→///         })
    73→///     }
    74→/// }
    75→/// ```
    76→pub trait TokenRefresher: Send + Sync {
    77→    /// Refresh the access token and return the new token.
    78→    ///
    79→    /// This method is called when the client encounters a `TokenExpired` error.
    80→    /// It should:
    81→    /// 1. Use the stored refresh token to get new access/refresh tokens
    82→    /// 2. Store the new tokens appropriately
    83→    /// 3. Return the new access token
    84→    ///
    85→    /// # Returns
    86→    /// A future that resolves to the new access token or an error.
    87→    ///
    88→    /// # Errors
    89→    /// - `AuthorizationRequired` - If the refresh token is also expired
    90→    /// - `RefreshFailed` - If the refresh request fails for other reasons
    91→    /// - `NetworkError` - If the refresh request fails due to network issues
    92→    fn refresh_token(&self) -> TokenRefreshResult;
    93→}
    94→
    95→/// Default request timeout in seconds
    96→const DEFAULT_TIMEOUT_SECS: u64 = 60;
    97→
    98→/// Upload timeout in seconds (longer for file uploads)
    99→const UPLOAD_TIMEOUT_SECS: u64 = 120;
   100→
   101→/// Default Garmin Connect API base URL
   102→const GARMIN_API_BASE_URL: &str = "https://connect.garmin.com/modern/proxy";
   103→
   104→/// Default Garmin Connect OAuth base URL (for token revocation)
   105→const GARMIN_OAUTH_BASE_URL: &str = "https://connect.garmin.com/oauth-service/oauth";
   106→
   107→/// FIT file header magic bytes
   108→const FIT_HEADER_SIZE: u8 = 14;
   109→const FIT_HEADER_SIGNATURE: &[u8] = b".FIT";
   110→
   111→/// Default retry delay in seconds when rate limited without Retry-After header
   112→const DEFAULT_RATE_LIMIT_RETRY_SECS: u64 = 60;
   113→
   114→/// Maximum retry attempts for transient errors
   115→const MAX_RETRY_ATTEMPTS: u32 = 3;
   116→
   117→/// Error categorization for retry and recovery logic
   118→///
   119→/// Classifies errors into categories that help determine the appropriate
   120→/// recovery strategy.
   121→#[derive(Debug, Clone, Copy, PartialEq, Eq)]
   122→pub enum ErrorCategory {
   123→    /// Transient errors that should be retried (network issues, timeouts)
   124→    Transient,
   125→    /// Rate limit errors that require waiting before retry
   126→    RateLimited,
   127→    /// Authentication errors requiring token refresh or re-authorization
   128→    Authentication,
   129→    /// Client errors that should not be retried (invalid data, bad request)
   130→    Client,
   131→    /// Server errors that may be retried after a delay
   132→    Server,
   133→    /// Permanent errors that should not be retried (duplicate activity)
   134→    Permanent,
   135→}
   136→
   137→impl ErrorCategory {
   138→    /// Check if errors in this category should be retried
   139→    pub fn is_retryable(&self) -> bool {
   140→        matches!(
   141→            self,
   142→            ErrorCategory::Transient | ErrorCategory::RateLimited | ErrorCategory::Server
   143→        )
   144→    }
   145→
   146→    /// Get the recommended initial retry delay in seconds
   147→    pub fn initial_retry_delay_secs(&self) -> u64 {
   148→        match self {
   149→            ErrorCategory::Transient => 5,
   150→            ErrorCategory::RateLimited => DEFAULT_RATE_LIMIT_RETRY_SECS,
   151→            ErrorCategory::Server => 30,
   152→            _ => 0, // Non-retryable
   153→        }
   154→    }
   155→
   156→    /// Get the maximum number of retry attempts for this category
   157→    pub fn max_retry_attempts(&self) -> u32 {
   158→        match self {
   159→            ErrorCategory::Transient => MAX_RETRY_ATTEMPTS,
   160→            ErrorCategory::RateLimited => 1, // Wait and retry once
   161→            ErrorCategory::Server => 2,
   162→            _ => 0, // Non-retryable
   163→        }
   164→    }
   165→}
   166→
   167→/// Rate limit information extracted from API response
   168→#[derive(Debug, Clone)]
   169→pub struct RateLimitInfo {
