   585→    /// This helper method wraps an API call and automatically handles token
   586→    /// refresh when the operation fails with `TokenExpired`. If a token refresher
   587→    /// is configured and the refresh succeeds, the operation is retried once.
   588→    ///
   589→    /// # Type Parameters
   590→    /// * `F` - The async factory function that creates the operation
   591→    /// * `T` - The return type of the operation
   592→    ///
   593→    /// # Arguments
   594→    /// * `operation_name` - Name of the operation for logging
   595→    /// * `operation_factory` - Factory function that creates the async operation
   596→    ///
   597→    /// # Returns
   598→    /// The result of the operation, or an error if the operation and refresh both fail
   599→    async fn with_auto_refresh<F, Fut, T>(
   600→        &self,
   601→        operation_name: &str,
   602→        operation_factory: F,
   603→    ) -> Result<T, SyncError>
   604→    where
   605→        F: Fn() -> Fut,
   606→        Fut: Future<Output = Result<T, SyncError>>,
   607→    {
   608→        let mut attempts = 0;
   609→
   610→        loop {
   611→            match operation_factory().await {
   612→                Ok(result) => return Ok(result),
   613→                Err(SyncError::TokenExpired) if attempts < MAX_AUTO_REFRESH_ATTEMPTS => {
   614→                    attempts += 1;
   615→                    tracing::info!(
